<?php
namespace App\Services;
use App\Models\Order;use App\Models\Payment;use Illuminate\Support\Facades\DB;
class PaymentService {public function record(Order $order,float $amount,string $method='cash',string $provider='manual',?string $reference=null):Payment{return DB::transaction(function()use($order,$amount,$method,$provider,$reference){if($amount<=0)abort(422,'Payment amount must be greater than zero.');$paid=(float)$order->payments()->where('status','paid')->sum('amount');$remaining=max(0,(float)$order->total_amount-$paid);if($amount>$remaining)abort(422,'Payment exceeds the outstanding order balance.');$payment=Payment::create(['order_id'=>$order->id,'reference'=>$reference?:'PAY-'.now()->format('YmdHis').'-'.strtoupper(substr(bin2hex(random_bytes(3)),0,6)),'provider'=>$provider,'method'=>$method,'amount'=>$amount,'status'=>'paid','paid_at'=>now()]);$newPaid=$paid+$amount;$order->update(['payment_status'=>$newPaid >= (float)$order->total_amount ? 'paid' : 'partial']);return $payment;});}}
